client_script:
// When ticket is selected in Attendees child table
frappe.web_form.on('attendes', {
    ticket: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.ticket) {
            frappe.db.get_value('Festa Ticket Type', row.ticket, ['price', 'currency'], (r) => {
                if (r) {
                    row.price = r.price || 0;
                    row.currency = r.currency || "USD";
                    frappe.web_form.refresh_field('attendees');
                    update_total_amount();
                }
            });
        }
    },
    price: function(frm, cdt, cdn) {
        update_total_amount();
    }
});

// Utility function to recalc total
function update_total_amount() {
    let total = 0;
    (frappe.web_form.doc.attendees || []).forEach(row => {
        total += flt(row.price);
    });
    frappe.web_form.set_value("total_amount", total);
}

frappe.ui.form.on("Festa Event", {
    refresh(frm) {

        // Existing buttons code here...

        // Add Pay Now button if event is published
        if (frm.doc.is_published && frm.doc.status === "Scheduled") {
            frm.add_custom_button(__("Pay Now"), () => {
                frappe.call({
                    method: "your_app.festa_event.create_payment_request",
                    args: { docname: frm.doc.name },
                    callback: function(r) {
                        if(r.message) {
                            frappe.msgprint(__("Payment Request Created: ") + r.message);
                            // Redirect to payment page
                            window.location.href = `/payment-request/${r.message}`;
                        }
                    }
                });
            }, __("Action")).addClass("btn-success");
        }
    },
});
